540→    #[test]
541→    fn load_merged_config_resolves_extends() {
542→        let server = MockServer::start();
543→
544→        let base_yaml = r#"
545→steps:
546→  lint:
547→    command: eslint .
548→    title: Lint code
549→"#;
550→
551→        server.mock(|when, then| {
552→            when.method(GET).path("/base.yml");
553→            then.status(200).body(base_yaml);
554→        });
555→
556→        let temp = TempDir::new().unwrap();
557→        let bivvy_dir = temp.path().join(".bivvy");
558→        fs::create_dir_all(&bivvy_dir).unwrap();
559→        fs::write(
560→            bivvy_dir.join("config.yml"),
561→            format!(
562→                r#"
563→extends:
564→  - url: {}
565→app_name: MyApp
566→steps:
567→  test:
568→    command: jest
569→"#,
570→                server.url("/base.yml")
571→            ),
572→        )
573→        .unwrap();
574→
575→        let resolver = resolver_for_mock(&server);
576→        let config = load_merged_config_with_resolver(temp.path(), &resolver).unwrap();
577→
578→        // Local app_name is preserved
579→        assert_eq!(config.app_name, Some("MyApp".to_string()));
