109→impl Command for RunCommand {
110→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
111→        // Load configuration
112→        let config = match load_merged_config(&self.project_root) {
113→            Ok(c) => c,
114→            Err(BivvyError::ConfigNotFound { .. }) => {
115→                ui.error("No configuration found. Run 'bivvy init' first.");
116→                return Ok(CommandResult::failure(2));
117→            }
118→            Err(e) => return Err(e),
119→        };
120→
121→        // Deprecation warning for --ci flag
122→        if self.args.ci {
123→            ui.warning(
124→                "--ci is deprecated and will be removed in 2.0. \
125→                 Use --non-interactive and --env ci instead.",
126→            );
127→        }
128→
129→        // Apply config default_output when no CLI flag was explicitly set.
130→        // OutputMode::Normal means the user didn't pass --verbose or --quiet.
131→        if ui.output_mode() == OutputMode::Normal {
132→            ui.set_output_mode(config.settings.default_output.into());
133→        }
134→
135→        // Resolve environment (before header so we can use resolved workflow)
136→        let resolved_env = self.resolve_environment(&config);
137→        let env_name = resolved_env.name.clone();
138→
139→        // Warn if the environment is not known
140→        if !resolved_env.is_known(&config) {
141→            ui.warning(&format!(
142→                "Unknown environment '{}'. It is not defined in settings.environments                  or a built-in. Step overrides for this environment will have no effect.",
143→                env_name
144→            ));
145→        }
146→
147→        // Get provided_requirements from environment config
148→        let provided_requirements: HashSet<String> = config
149→            .settings
150→            .environments
151→            .get(&env_name)
152→            .map(|env_config| env_config.provided_requirements.iter().cloned().collect())
153→            .unwrap_or_default();
154→
155→        // Use environment's default_workflow if no explicit --workflow and config has one
156→        let workflow_name = if self.args.workflow == "default" {
157→            config
158→                .settings
159→                .environments
160→                .get(&env_name)
161→                .and_then(|env_config| env_config.default_workflow.clone())
162→                .unwrap_or_else(|| self.args.workflow.clone())
163→        } else {
164→            self.args.workflow.clone()
165→        };
166→
167→        // Show header
168→        let app_name = config.app_name.as_deref().unwrap_or("project");
169→        let step_count = config
170→            .workflows
171→            .get(workflow_name.as_str())
172→            .map(|w| w.steps.len())
173→            .unwrap_or(0);
174→        ui.show_run_header(
175→            app_name,
176→            &workflow_name,
177→            step_count,
178→            crate::updates::version::VERSION,
179→        );
180→
181→        // Show environment and config info
182→        ui.message(&format!(
183→            "  Environment: {} ({})",
184→            env_name, resolved_env.source
185→        ));
186→
187→        if self.args.dry_run {
188→            let paths = ConfigPaths::discover(&self.project_root);
189→            if let Some(project_path) = &paths.project {
190→                ui.message(&format!("Config: {}", project_path.display()));
191→            }
192→        }
193→
194→        // Check for dry-run mode
195→        if self.args.dry_run {
196→            ui.message("Running in dry-run mode - no commands will be executed");
197→        }
198→
199→        // Get project identity
200→        let project_id = ProjectId::from_path(&self.project_root)?;

  1→//! Configuration file discovery and loading.
  2→//!
  3→//! This module handles finding and loading configuration files from
  4→//! various locations in the correct priority order.
  5→
  6→use crate::config::extends::ExtendsResolver;
  7→use crate::config::merger::merge_configs;
  8→use crate::config::schema::BivvyConfig;
  9→use crate::error::{BivvyError, Result};
 10→use std::fs;
 11→use std::path::{Path, PathBuf};
 12→
 13→/// Paths to configuration files in priority order (later overrides earlier).
 14→///
 15→/// Merge order:
 16→/// 1. Remote base configs (from `extends:`)
 17→/// 2. User global config (`~/.bivvy/config.yml`)
 18→/// 3. Project config (`.bivvy/config.yml`)
 19→/// 4. Local overrides (`.bivvy/config.local.yml`)
 20→#[derive(Debug, Clone)]
 21→pub struct ConfigPaths {
 22→    /// Remote base config (if extends: is used)
 23→    pub extends: Vec<PathBuf>,
 24→
 25→    /// User's global config: ~/.bivvy/config.yml
 26→    pub user_global: Option<PathBuf>,
 27→
 28→    /// Project config: .bivvy/config.yml
 29→    pub project: Option<PathBuf>,
 30→
 31→    /// Local overrides: .bivvy/config.local.yml
 32→    pub project_local: Option<PathBuf>,
 33→}
 34→
 35→impl ConfigPaths {
 36→    /// Discover config files for the given project root.
 37→    pub fn discover(project_root: &Path) -> Self {
 38→        Self {
 39→            extends: Vec::new(), // Populated later after parsing project config
 40→            user_global: Self::find_user_global(),
 41→            project: Self::find_project_config(project_root),
 42→            project_local: Self::find_project_local(project_root),
 43→        }
 44→    }
 45→
 46→    /// Find user's global config at ~/.bivvy/config.yml
 47→    fn find_user_global() -> Option<PathBuf> {
 48→        let path = dirs::home_dir()?.join(".bivvy").join("config.yml");
 49→        if path.exists() {
 50→            Some(path)
 51→        } else {
 52→            None
 53→        }
 54→    }
 55→
 56→    /// Find project config at .bivvy/config.yml
 57→    fn find_project_config(project_root: &Path) -> Option<PathBuf> {
 58→        let path = project_root.join(".bivvy").join("config.yml");
 59→        if path.exists() {
 60→            Some(path)
 61→        } else {
 62→            None
 63→        }
 64→    }
 65→
 66→    /// Find local overrides at .bivvy/config.local.yml
 67→    fn find_project_local(project_root: &Path) -> Option<PathBuf> {
 68→        let path = project_root.join(".bivvy").join("config.local.yml");
 69→        if path.exists() {
 70→            Some(path)
 71→        } else {
 72→            None
 73→        }
 74→    }
 75→
 76→    /// Returns all existing config paths in merge order.
 77→    pub fn all_existing(&self) -> Vec<&PathBuf> {
 78→        let mut paths = Vec::new();
 79→
 80→        for p in &self.extends {
 81→            paths.push(p);
 82→        }
 83→
 84→        if let Some(p) = &self.user_global {
 85→            paths.push(p);
 86→        }
 87→
 88→        if let Some(p) = &self.project {
 89→            paths.push(p);
 90→        }
 91→
 92→        if let Some(p) = &self.project_local {
 93→            paths.push(p);
 94→        }
 95→
 96→        paths
 97→    }
 98→
 99→    /// Check if any project config exists.
100→    pub fn has_project_config(&self) -> bool {
101→        self.project.is_some()
102→    }
103→}
104→
105→/// Find the project root by walking up from current directory.
106→///
107→/// Looks for:
108→/// 1. `.bivvy` directory (primary indicator)
109→/// 2. `.git` directory (fallback)
110→///
111→/// # Returns
112→///
113→/// The path to the project root, or None if not found.
114→pub fn find_project_root(start: &Path) -> Option<PathBuf> {
115→    let mut current = start.to_path_buf();
116→
117→    loop {
118→        // Check for .bivvy directory
119→        if current.join(".bivvy").is_dir() {
120→            return Some(current);
121→        }
122→
123→        // Check for .git directory (fallback)
124→        if current.join(".git").exists() {
125→            return Some(current);
126→        }
127→
128→        // Move up one directory
129→        if !current.pop() {
130→            return None;
131→        }
132→    }
133→}
